package ons

import _ "embed"

// The JSON is generated by cmd/onsconvert and embedded so the server binary
// needs no data files at runtime.
//
//go:embed data/region2019.json
var region2019 []byte

// Region2019 returns the ONS Family Spending 2019 expenditure-by-region table.
func Region2019() (*Dataset, error) {
	return Parse(region2019)
}
